namespace fs=std::filesystem;
using Row=std::vector<std::string>;
Row split(const std::string&s){Row r;std::string v;bool q=false;for(size_t i=0;i<s.size();++i){char c=s[i];if(c=='"'){if(q&&i+1<s.size()&&s[i+1]=='"'){v+=c;++i;}else q=!q;}else if(c==','&&!q){r.push_back(v);v.clear();}else if(c!='\r')v+=c;}if(q)throw std::runtime_error("unclosed CSV quote");r.push_back(v);return r;}
int integer(const std::string&s){size_t n;int x=std::stoi(s,&n);if(n!=s.size())throw std::runtime_error("bad integer");return x;}
double number(const std::string&s){size_t n;double x=std::stod(s,&n);if(n!=s.size()||!std::isfinite(x))throw std::runtime_error("bad finite number");return x;}
struct M{int cell,status;bool peak,width;double amp,tm,w;};
using Settings=std::array<int,4>;
std::map<int,Settings> settings;
std::map<int,std::vector<M>> data;
struct Fit{int n=0;double a=NAN,b=NAN,se=NAN,rms=NAN,r2=NAN,xlo=NAN,xhi=NAN;double eval(double x)const{return a+b*x;}};
Fit fit(const std::vector<double>&x,const std::vector<double>&y){if(x.size()!=y.size())throw std::runtime_error("fit sizes");Fit f;f.n=x.size();if(f.n<3)return f;double mx=std::accumulate(x.begin(),x.end(),0.)/f.n,my=std::accumulate(y.begin(),y.end(),0.)/f.n,sxx=0,sxy=0,syy=0;for(int i=0;i<f.n;++i){sxx+=pow(x[i]-mx,2);sxy+=(x[i]-mx)*(y[i]-my);syy+=pow(y[i]-my,2);}if(sxx<=0)return f;f.b=sxy/sxx;f.a=my-f.b*mx;double sse=0;for(int i=0;i<f.n;++i)sse+=pow(y[i]-f.eval(x[i]),2);f.se=sqrt(sse/(f.n-2)/sxx);f.rms=sqrt(sse/f.n);f.r2=syy>0?1-sse/syy:NAN;f.xlo=*min_element(x.begin(),x.end());f.xhi=*max_element(x.begin(),x.end());return f;}
double quant(std::vector<double>v,double q){if(v.empty())return NAN;sort(v.begin(),v.end());double t=q*(v.size()-1);size_t i=floor(t),j=ceil(t);return v[i]+(t-i)*(v[j]-v[i]);}
std::vector<double> values(int run,int layer,bool amp=false){std::vector<double> v;for(auto&m:data.at(run))if((m.cell&63)==layer&&(amp?m.peak:m.width))v.push_back(amp?m.amp:m.w);return v;}
void readDB(const std::string&path){std::ifstream f(path);std::string s;Row h;while(getline(f,s))if(s.rfind("Run Number,",0)==0){h=split(s);break;}if(h.empty())throw std::runtime_error("DB header missing");std::array<size_t,4> col;for(int i=0;i<4;++i){std::string name=std::array<std::string,4>{"RF","CF","CC","CFComp"}[i];auto it=find(h.begin(),h.end(),name);if(it==h.end())throw std::runtime_error("DB setting missing");col[i]=it-h.begin();}while(getline(f,s)){if(s.empty())continue;auto r=split(s);int run=integer(r[0]);Settings st;for(int i=0;i<4;++i)st[i]=integer(r.at(col[i]));if(!settings.emplace(run,st).second)throw std::runtime_error("duplicate run DB");}}
void readData(const std::string&manifest){std::ifstream f(manifest);std::string s;getline(f,s);if(split(s)!=Row{"run","measurements_csv"})throw std::runtime_error("manifest header");while(getline(f,s)){if(s.empty())continue;auto r=split(s);int run=integer(r.at(0));if(data.count(run))throw std::runtime_error("duplicate run manifest");auto path=fs::path(manifest).parent_path()/r.at(1);std::ifstream in(path);if(!in)throw std::runtime_error("missing CSV "+path.string());getline(in,s);auto h=split(s);if(h!=Row{"run","cell","status","has_peak","has_fwhm","peak_bin","left_bin","right_bin","amplitude","peak_time_ns","left_ns","right_ns","fwhm_ns","source"})throw std::runtime_error("measurement header");std::set<int> cells;auto& out=data[run];while(getline(in,s)){if(s.empty())continue;auto z=split(s);if(z.size()!=14||integer(z[0])!=run)throw std::runtime_error("CSV identity");M m{};m.cell=integer(z[1]);m.status=integer(z[2]);int hp=integer(z[3]),hw=integer(z[4]);if((hp!=0&&hp!=1)||(hw!=0&&hw!=1)||m.status<0||m.status>7||hw>hp)throw std::runtime_error("invalid flags");m.peak=hp;m.width=hw;if(m.peak){m.amp=number(z[8]);m.tm=number(z[9]);if(m.amp<=0)throw std::runtime_error("nonpositive peak");}if(m.width){m.w=number(z[12]);if(m.w<=0||fabs(m.w-(number(z[11])-number(z[10])))>1e-6||m.status!=0)throw std::runtime_error("inconsistent width");}if(!cells.insert(m.cell).second)throw std::runtime_error("duplicate cell");out.push_back(m);}if(out.size()!=64)throw std::runtime_error("expected 64 cells");for(int l=0;l<8;++l){int n=0;for(auto&m:out)if((m.cell&63)==l)++n;if(n!=8)throw std::runtime_error("expected 8 cells per layer");}if(!settings.count(run))throw std::runtime_error("missing run DB");}}
struct Scan{std::string name;int index;std::vector<int> runs;std::string fixed;double nominal;};
std::vector<Scan> scans={{"RF",0,{298,300,302,304,306,310,329,333,335,337,339,341,343,345},"CF7 / CC5 / CFComp1",80./9},{"CF",1,{361,355,363,298},"RF9 / CC5 / CFComp1",7},{"CFComp",3,{355,357,359},"RF9 / CF5 / CC5",1},{"CC",2,{353,347,298,349,351},"RF9 / CF7 / CFComp1",5}};
// Optional scan manifest explicitly selects run membership; settings are still validated.
void configureScans(const std::string& path) {
  if(path.empty()) { if(data.count(331)) scans[0].runs.push_back(331); return; }
  std::ifstream in(path); std::string line;
  if(!getline(in,line)||split(line)!=Row{"scan","run"}) throw std::runtime_error("scan manifest header must be scan,run");
  for(auto& scan:scans) scan.runs.clear();
  while(getline(in,line)) { if(line.empty()) continue; auto row=split(line);
    if(row.size()!=2) throw std::runtime_error("scan manifest row");
    auto it=std::find_if(scans.begin(),scans.end(),[&](const Scan& v){return v.name==row[0];});
    if(it==scans.end()) throw std::runtime_error("unknown scan "+row[0]);
    int run=integer(row[1]);
    if(std::find(it->runs.begin(),it->runs.end(),run)!=it->runs.end()) throw std::runtime_error("duplicate scan run");
    it->runs.push_back(run);
  }
  for(const auto& scan:scans) if(scan.runs.size()<3) throw std::runtime_error("each scan needs at least 3 acquisitions");
}
std::string rfStatus() {
  bool included=std::find(scans[0].runs.begin(),scans[0].runs.end(),331)!=scans[0].runs.end();
  return included ? "RF7/run331 included" : "RF7/run331 not included";
}
void makeManifest(const std::string& directory,const std::string& output) {
  if(fs::exists(output)) throw std::runtime_error("refusing existing manifest");
  std::map<int,fs::path> found;
  for(const auto& e:fs::recursive_directory_iterator(directory)) {
    if(!e.is_regular_file()) continue;
    std::string name=e.path().filename().string(),prefix="WaveformGrid_Run",suffix="_Measurements.csv";
    if(name.rfind(prefix,0)!=0||name.size()<=prefix.size()+suffix.size()||name.substr(name.size()-suffix.size())!=suffix) continue;
    int run=integer(name.substr(prefix.size(),name.size()-prefix.size()-suffix.size()));
    if(!found.emplace(run,fs::absolute(e.path())).second) throw std::runtime_error("duplicate CSV for run "+std::to_string(run)+"; select a clean archive root");
  }
  if(found.empty()) throw std::runtime_error("no WaveformGrid_Run*_Measurements.csv files found");
  std::ofstream out(output); if(!out) throw std::runtime_error("cannot write manifest");
  out<<"run,measurements_csv\n";
  for(const auto& [run,path]:found) { std::string escaped; for(char c:path.string()) {escaped+=c;if(c=='"')escaped+=c;} out<<run<<",\""<<escaped<<"\"\n"; }
  std::cout<<"Wrote "<<found.size()<<" runs to "<<output<<"\n";
}
double xval(const Scan&s,int run){int code=settings.at(run)[s.index];return s.name=="RF"?80./code:code;}
std::string xlabel(const Scan&s){return s.name=="RF"?"Nominal R_{F}=80/code [k#Omega] (provisional)":s.name+" register code";}
Fit layerFit(const Scan&s,int layer,bool all=false,bool amp=false){std::vector<double>x,y;for(int run:s.runs){if(!all&&s.name=="RF"&&settings.at(run)[0]==1)continue;auto v=values(run,layer,amp);if(v.empty())continue;x.push_back(xval(s,run));y.push_back(quant(v,.5));}return fit(x,y);}
void text(double x,double y,const std::string&s,double size=.035,int color=1){TLatex l;l.SetNDC();l.SetTextFont(42);l.SetTextSize(size);l.SetTextColor(color);l.DrawLatex(x,y,s.c_str());}
std::string fmt(double x,int p=3){if(!std::isfinite(x))return "undefined";std::ostringstream o;o<<std::setprecision(p)<<x;return o.str();}
std::string pdf,outdir;TFile* rootout=nullptr;int page=0;
void save(TCanvas&c,const std::string&name){c.Update();c.Print(pdf.c_str());c.Print((outdir+"/"+name+".png").c_str());rootout->cd();c.Write(name.c_str());++page;}
void header(TCanvas&c,const std::string&title,const std::string&sub){c.cd();text(.025,.97,title,.027);text(.025,.935,sub,.018);}
void trend(const Scan&s,bool zoom=false,bool residual=false,bool amp=false){TCanvas c("trend","",1600,1000);header(c,s.name+" / "+(amp?"peak amplitude":"FWHM")+(residual?" linear-fit residuals":" by encoded layer"),s.fixed+" | "+rfStatus()+" | saved mean-profile measurements, no channel rejection");auto container=new TPad("panels","",0,.055,1,.905);container->Draw();container->cd();container->Divide(4,2,.002,.003);for(int l=0;l<8;++l){container->cd(l+1);gPad->SetLeftMargin(.15);gPad->SetBottomMargin(.18);gPad->SetTopMargin(.12);gPad->SetRightMargin(.035);Fit f=layerFit(s,l,false,amp),fa=layerFit(s,l,true,amp);double xmin=1e99,xmax=-1e99,ymin=1e99,ymax=-1e99;for(int run:s.runs){if(zoom&&s.name=="RF"&&settings.at(run)[0]==1)continue;double x=xval(s,run);xmin=std::min(xmin,x);xmax=std::max(xmax,x);for(double y:values(run,l,amp)){if(residual)y-=f.eval(x);ymin=std::min(ymin,y);ymax=std::max(ymax,y);}}double dx=(xmax-xmin)*.06,dy=(ymax-ymin)*.12;if(dy<1)dy=1;auto frame=gPad->DrawFrame(xmin-dx,ymin-dy,xmax+dx,ymax+3*dy);frame->SetTitle(("L"+std::to_string(l)+"  ("+(l<4?"5":"10")+"-layer sum)").c_str());frame->GetXaxis()->SetTitle(xlabel(s).c_str());frame->GetYaxis()->SetTitle((amp?"Peak [ADC]":residual?"FWHM - fit [ns]":"FWHM [ns]"));frame->GetXaxis()->SetTitleSize(.042);frame->GetYaxis()->SetTitleSize(.047);frame->GetXaxis()->SetLabelSize(.04);frame->GetYaxis()->SetLabelSize(.04);frame->GetYaxis()->SetTitleOffset(1.4);auto nominal=new TLine(s.nominal,ymin-dy,s.nominal,ymax+dy);nominal->SetLineColor(kGreen+2);nominal->SetLineStyle(3);nominal->Draw();if(residual){auto z=new TLine(xmin-dx,0,xmax+dx,0);z->SetLineStyle(2);z->Draw();}else if(std::isfinite(f.b)){auto line=new TLine(f.xlo,f.eval(f.xlo),f.xhi,f.eval(f.xhi));line->SetLineColor(kBlue+1);line->SetLineWidth(2);line->Draw();if(s.name=="RF"&&!zoom){auto a=new TLine(fa.xlo,fa.eval(fa.xlo),fa.xhi,fa.eval(fa.xhi));a->SetLineStyle(2);a->SetLineColor(kRed+1);a->Draw();}}
for(int run:s.runs){if(zoom&&s.name=="RF"&&settings.at(run)[0]==1)continue;double x=xval(s,run);auto v=values(run,l,amp);if(v.empty())continue;auto cloud=new TGraph();for(size_t j=0;j<v.size();++j)cloud->SetPoint(j,x,v[j]-(residual?f.eval(x):0));cloud->SetMarkerStyle(24);cloud->SetMarkerSize(.6);cloud->SetMarkerColor(kGray+1);cloud->Draw("P SAME");double med=quant(v,.5),low=quant(v,.25),hi=quant(v,.75);auto g=new TGraphAsymmErrors(1);g->SetPoint(0,x,med-(residual?f.eval(x):0));g->SetPointError(0,0,0,med-low,hi-med);g->SetMarkerStyle(run==363?25:20);g->SetMarkerSize(.9);g->SetLineWidth(2);g->SetMarkerColor(run==363?kMagenta+1:kBlack);g->SetLineColor(run==363?kMagenta+1:kBlack);g->Draw("P SAME");}
text(.18,.82,"slope = "+fmt(f.b)+" #pm "+fmt(f.se),.038,kBlue+1);text(.18,.76,"RMS residual = "+fmt(f.rms)+(amp?" ADC":" ns"),.036);text(.18,.70,"n="+std::to_string(f.n)+" run medians",.036);}
c.cd();text(.025,.032,"Black: median and IQR across channels (NOT measurement errors); gray: every extracted channel. Green: nominal.",.017);text(.025,.010,s.name=="RF"?"Blue: OLS RF codes 2-15; red dashed: all codes sensitivity. RF1 retained diagnostically; no physics exclusion established.":"Unweighted OLS of run medians. Slope +/- is residual-based OLS SE, not a calibrated statistical uncertainty. Magenta: run363 CF5 repeat (run355 black).",.016);save(c,s.name+(amp?"_amplitude":residual?"_residuals":zoom?"_zoom":"_full"));}
void nominal(){TCanvas c("nominal","",1500,950);header(c,"Nominal setting: layer and summation comparisons","Run298 | RF9 / CF7 / CC5 / CFComp1 | encoded layers are not equal physical depths");auto p=new TPad("np","",0,.07,1,.91);p->Draw();p->Divide(2,1);for(int metric=0;metric<2;++metric){p->cd(metric+1);gPad->SetLeftMargin(.14);gPad->SetBottomMargin(.13);double ymax=0;for(int l=0;l<8;++l)for(double y:values(298,l,metric))ymax=std::max(ymax,y);auto h=gPad->DrawFrame(-.5,0,7.5,ymax*1.2);h->GetXaxis()->SetTitle("Encoded layer / segment");h->GetYaxis()->SetTitle(metric?"Peak [ADC]":"FWHM [ns]");for(int l=0;l<8;++l){auto v=values(298,l,metric);auto cloud=new TGraph();for(size_t i=0;i<v.size();++i)cloud->SetPoint(i,l+(double(i)-3.5)*.035,v[i]);cloud->SetMarkerStyle(24);cloud->SetMarkerColor(kGray+1);cloud->Draw("P");auto g=new TGraphAsymmErrors(1);double m=quant(v,.5);g->SetPoint(0,l,m);g->SetPointError(0,0,0,m-quant(v,.25),quant(v,.75)-m);g->SetMarkerStyle(20);g->SetLineWidth(2);g->Draw("P");}auto line=new TLine(3.5,0,3.5,ymax*1.2);line->SetLineStyle(2);line->Draw();text(.18,.84,"L0-L3: 5-layer sums",.033);text(.55,.84,"L4-L7: 10-layer sums",.033);}c.cd();text(.025,.038,"Each segment has eight distinct readout positions. IQR represents channel spread, not uncertainty on a median.",.019);text(.025,.012,"This is an observational comparison, not a controlled 5-versus-10 experiment or proof of added capacitance.",.019);save(c,"Nominal_layers");}
void shifts(std::ofstream&csv){TCanvas c("shifts","",1500,900);header(c,"Equivalent setting offsets: bring another layer to nominal L0 width","delta setting(L) = [median W(L0, run298) - median W(L, run298)] / fitted slope(L)");auto p=new TPad("sp","",0,.16,1,.90);p->Draw();p->Divide(2,1);for(int k=0;k<2;++k){auto&s=scans[k];double w0=quant(values(298,0),.5);p->cd(k+1);gPad->SetLeftMargin(.15);gPad->SetBottomMargin(.16);auto g=new TGraph();auto bad=new TGraph();double lo=0,hi=0;int stable=0;for(int l=0;l<8;++l){Fit f=layerFit(s,l);bool usable=std::isfinite(f.b)&&fabs(f.b)>2*f.se;double wt=quant(values(298,l),.5);csv<<s.name<<","<<l<<","<<w0<<","<<wt<<","<<f.b<<","<<f.se<<",";if(!usable){csv<<",,,unstable_slope\n";continue;}double d=(w0-wt)/f.b,ab=s.nominal+d;bool ext=ab<f.xlo||ab>f.xhi;csv<<d<<","<<ab<<","<<ext<<","<<(ab<=0&&k==0?"nonphysical_extrapolation":ext?"extrapolation":"within_scan_linearized")<<"\n";lo=std::min(lo,d);hi=std::max(hi,d);auto*dst=ext?bad:g;dst->SetPoint(dst->GetN(),l,d);++stable;}
if(stable){double pad=std::max(1.,(hi-lo)*.15);auto h=gPad->DrawFrame(-.5,lo-pad,7.5,hi+pad);h->SetTitle((s.name+" layer-specific response").c_str());h->GetXaxis()->SetTitle("Layer to be adjusted toward nominal L0 width");h->GetYaxis()->SetTitle(k?"Equivalent #DeltaCF [register codes]":"Equivalent #DeltaR_{F} [k#Omega] (provisional)");g->SetMarkerStyle(20);g->SetMarkerSize(1.5);g->SetMarkerColor(kBlue+1);g->Draw("P");bad->SetMarkerStyle(24);bad->SetMarkerSize(1.5);bad->SetMarkerColor(kRed+1);bad->Draw("P");text(.18,.84,"Blue: within scan; red: extrapolated",.031);text(.18,.78,"Nominal R_{F} = 8.89 k#Omega (provisional)",.03);}else{text(.15,.78,"CF equivalent shifts not supported",.043,kRed+1);text(.15,.67,"Every layer's slope has |b| #leq 2 SE.",.035);text(.15,.59,"Too little stable response for division.",.035);text(.15,.51,"Dividing by these weak slopes is unstable.",.035);text(.15,.40,"Inspect fit table and repeated-setting scatter.",.035);text(.15,.32,"This does not establish zero capacitance effect.",.032);}}
c.cd();text(.025,.12,"Linearized, nominal-anchored descriptive offsets, not exact inverse fits or physical estimates of trace resistance/capacitance.",.019);text(.025,.085,"No confidence intervals: channel spread and repeated acquisitions do not establish measurement-error covariance.",.019);text(.025,.05,"A 2-SE slope screen is a diagnostic safeguard, not a significance test; red offsets outside scan are not validated predictions.",.019);text(.025,.015,"Negative absolute resistance is nonphysical. Inspect equivalent_shifts.csv and fit residuals before using any offset.",.019);save(c,"Equivalent_shifts");}
void selftest(){auto f=fit({1,2,3,4},{3,5,7,9});if(fabs(f.a-1)>1e-12||fabs(f.b-2)>1e-12||f.se>1e-12)throw std::runtime_error("OLS selftest");if(quant({1,2,3,4},.5)!=2.5||quant({1,2,3,4},.25)!=1.75)throw std::runtime_error("quantile selftest");if(split("1,\"a,b\",3")!=Row{"1","a,b","3"})throw std::runtime_error("CSV selftest");if(std::isfinite(fit({1,1,1},{1,2,3}).b))throw std::runtime_error("singular selftest");std::cout<<"Selftests passed\n";}
int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="--self-test"){selftest();return 0;}if(argc==4&&std::string(argv[1])=="--make-manifest"){makeManifest(argv[2],argv[3]);return 0;}if(argc!=4&&argc!=5)throw std::runtime_error("usage AriLayerTrends manifest.csv MayRunDB.csv NEW_OUTPUT_DIRECTORY [scan_runs.csv]; or --make-manifest ARCHIVE_ROOT NEW_MANIFEST.csv");selftest();readDB(argv[2]);readData(argv[1]);configureScans(argc==5?argv[4]:"");if(data.count(331)&&settings.at(331)!=Settings{7,7,5,1})throw std::runtime_error("run331 RF7 settings mismatch");if(settings.at(298)!=Settings{9,7,5,1})throw std::runtime_error("nominal mismatch");for(auto&s:scans){for(int run:s.runs){if(!data.count(run))throw std::runtime_error("missing required run "+std::to_string(run));auto st=settings.at(run);auto base=s.name=="CFComp"?Settings{9,5,5,1}:Settings{9,7,5,1};for(int k=0;k<4;++k)if(k!=s.index&&st[k]!=base[k])throw std::runtime_error("scan fixed setting mismatch");}sort(s.runs.begin(),s.runs.end(),[&](int a,int b){return xval(s,a)==xval(s,b)?a<b:xval(s,a)<xval(s,b);});}outdir=argv[3];if(fs::exists(outdir))throw std::runtime_error("refusing existing output directory");fs::create_directories(outdir);gROOT->SetBatch();gStyle->SetOptStat(0);gStyle->SetTitleFontSize(.055);pdf=outdir+"/Adam_Layer_Trends_PRELIMINARY.pdf";TFile outf((outdir+"/Adam_Layer_Trends.root").c_str(),"RECREATE");rootout=&outf;TCanvas opener;opener.Print((pdf+"[").c_str());std::ofstream fits(outdir+"/linear_fits.csv");fits<<"scan,layer,selection,n,intercept,slope,slope_OLS_SE,RMS_residual,R2,x_min,x_max\n";fits<<std::setprecision(12);for(auto&s:scans){trend(s);if(s.name=="RF")trend(s,true);trend(s,s.name=="RF",true);for(int l=0;l<8;++l)for(bool all:{false,true}){if(all&&s.name!="RF")continue;auto f=layerFit(s,l,all);fits<<s.name<<","<<l<<","<<(all?"all_codes":"diagnostic_reference")<<","<<f.n<<","<<f.a<<","<<f.b<<","<<f.se<<","<<f.rms<<","<<f.r2<<","<<f.xlo<<","<<f.xhi<<"\n";}}trend(scans[0],true,false,true);nominal();std::ofstream eq(outdir+"/equivalent_shifts.csv");eq<<"scan,target_layer,nominal_L0_median,nominal_target_median,target_layer_slope,target_layer_slope_OLS_SE,delta_setting,equivalent_absolute_setting,extrapolated,status\n";eq<<std::setprecision(12);shifts(eq);std::ofstream summary(outdir+"/layer_measurements.csv");summary<<"run,RF,CF,CC,CFComp,layer,n_width,median_width_ns,Q1_ns,Q3_ns,median_peak_ADC\n";for(auto&[r,ms]:data)for(int l=0;l<8;++l){auto v=values(r,l);auto st=settings.at(r);summary<<r<<","<<st[0]<<","<<st[1]<<","<<st[2]<<","<<st[3]<<","<<l<<","<<v.size()<<","<<quant(v,.5)<<","<<quant(v,.25)<<","<<quant(v,.75)<<","<<quant(values(r,l,true),.5)<<"\n";}opener.Print((pdf+"]").c_str());outf.Close();std::cout<<"Wrote "<<page<<" pages for "<<data.size()<<" runs. "<<rfStatus()<<".\n";return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
